import React, { useState } from 'react';
import { useWidgetDraggable, useWidgetResizable, useWidgetAI } from '../hooks/useWidgetHooks';
import '../styles/CalculatorWidget.css';

const CalculatorWidget = () => {
  const widgetId = 'calculator-widget';
  const draggable = useWidgetDraggable(widgetId);
  const resizable = useWidgetResizable(widgetId, { width: 380, height: 500 });
  const { callGemini, loading: aiLoading } = useWidgetAI();

  const [display, setDisplay] = useState('0');
  const [previousValue, setPreviousValue] = useState(null);
  const [operation, setOperation] = useState(null);
  const [waitingForOperand, setWaitingForOperand] = useState(false);
  const [tab, setTab] = useState('basic');
  const [angleMode, setAngleMode] = useState('deg');
  const [nlInput, setNlInput] = useState('');
  const [nlResult, setNlResult] = useState(null);

  // Natural Language Math Interpretation
  const interpretMathQuery = async () => {
    const prompt = `You are a calculator AI. The user gave this math instruction:

"${nlInput}"

Extract and solve:
1. The mathematical expression or question
2. Show the calculation step-by-step
3. Provide the final answer

Format as:
Expression: [the math]
Steps: [brief steps]
Answer: [result]

Be concise and accurate.`;

    const result = await callGemini(prompt);
    if (result.success) {
      setNlResult({
        query: nlInput,
        result: result.content,
        timestamp: new Date().toLocaleTimeString(),
      });
      setNlInput('');
    }
  };

  // Input digit
  const inputDigit = (digit) => {
    if (waitingForOperand) {
      setDisplay(String(digit));
      setWaitingForOperand(false);
    } else {
      setDisplay(display === '0' ? String(digit) : display + digit);
    }
  };

  // Input decimal
  const inputDecimal = () => {
    if (waitingForOperand) {
      setDisplay('0.');
      setWaitingForOperand(false);
    } else if (display.indexOf('.') === -1) {
      setDisplay(display + '.');
    }
  };

  // Clear display
  const clear = () => {
    setDisplay('0');
    setPreviousValue(null);
    setOperation(null);
    setWaitingForOperand(true);
  };

  // Delete last character
  const backspace = () => {
    if (display.length > 1) {
      setDisplay(display.slice(0, -1));
    } else {
      setDisplay('0');
    }
  };

  // Perform operation
  const performOperation = (nextOperation) => {
    const inputValue = parseFloat(display);

    if (previousValue === null) {
      setPreviousValue(inputValue);
    } else if (operation) {
      const result = calculate(previousValue, inputValue, operation);
      setDisplay(String(result));
      setPreviousValue(result);
    }

    setWaitingForOperand(true);
    setOperation(nextOperation);
  };

  // Calculate result
  const calculate = (prev, current, op) => {
    switch (op) {
      case '+':
        return prev + current;
      case '-':
        return prev - current;
      case '*':
        return prev * current;
      case '/':
        return prev / current;
      case '%':
        return prev % current;
      case '^':
        return Math.pow(prev, current);
      default:
        return current;
    }
  };

  // Equals button
  const equals = () => {
    const inputValue = parseFloat(display);

    if (previousValue !== null && operation) {
      const result = calculate(previousValue, inputValue, operation);
      setDisplay(String(result));
      setPreviousValue(null);
      setOperation(null);
      setWaitingForOperand(true);
    }
  };

  // Scientific function
  const scientificFunc = (func) => {
    let value = parseFloat(display);
    let result;

    if (func === 'sin') {
      const radian = angleMode === 'deg' ? (value * Math.PI) / 180 : value;
      result = Math.sin(radian);
    } else if (func === 'cos') {
      const radian = angleMode === 'deg' ? (value * Math.PI) / 180 : value;
      result = Math.cos(radian);
    } else if (func === 'tan') {
      const radian = angleMode === 'deg' ? (value * Math.PI) / 180 : value;
      result = Math.tan(radian);
    } else if (func === 'sqrt') {
      result = Math.sqrt(value);
    } else if (func === 'log') {
      result = Math.log10(value);
    } else if (func === 'ln') {
      result = Math.log(value);
    } else if (func === 'e') {
      result = Math.E;
    } else if (func === 'pi') {
      result = Math.PI;
    } else if (func === 'factorial') {
      result = factorial(Math.floor(value));
    } else {
      result = value;
    }

    setDisplay(String(result));
    setWaitingForOperand(true);
  };

  // Factorial
  const factorial = (n) => {
    if (n === 0 || n === 1) return 1;
    let result = 1;
    for (let i = 2; i <= n; i++) {
      result *= i;
    }
    return result;
  };

  // Button style
  const btnStyle = {
    padding: '12px',
    border: '1px solid #00ff88',
    backgroundColor: '#1a1f3a',
    color: '#00ff88',
    borderRadius: '4px',
    cursor: 'pointer',
    fontWeight: 'bold',
    fontSize: '14px',
    transition: 'all 0.2s',
  };

  const operatorStyle = {
    ...btnStyle,
    backgroundColor: '#00ff8833',
    borderColor: '#00ff88',
    color: '#ffff00',
  };

  const equalsStyle = {
    ...btnStyle,
    backgroundColor: '#00ff88',
    color: '#0a0e27',
    fontWeight: 'bold',
  };

  return (
    <div
      {...draggable}
      ref={draggable.ref}
      {...resizable}
      className="widget-container"
      style={{
        ...draggable.style,
        ...resizable.style,
        position: 'fixed',
        zIndex: 1000,
        backgroundColor: '#0a0e27',
        border: '2px solid #00ff88',
        borderRadius: '8px',
        boxShadow: '0 0 20px rgba(0, 255, 136, 0.3)',
        display: 'flex',
        flexDirection: 'column',
      }}
    >
      {/* Header */}
      <div style={{ borderBottom: '2px solid #00ff88', padding: '12px' }}>
        <div style={{ color: '#00ff88', fontSize: '16px', fontWeight: 'bold' }}>
          🔢 SCIENTIFIC CALCULATOR
        </div>
        <div style={{ fontSize: '11px', color: '#00aa66' }}>
          ● Natural Language Math Enabled
        </div>
      </div>

      {/* Tabs */}
      <div style={{ display: 'flex', borderBottom: '1px solid #00ff88', gap: '8px', padding: '8px' }}>
        {['basic', 'scientific', 'nl-math'].map((t) => (
          <button
            key={t}
            onClick={() => setTab(t)}
            style={{
              background: tab === t ? '#00ff88' : 'transparent',
              color: tab === t ? '#0a0e27' : '#00ff88',
              border: '1px solid #00ff88',
              padding: '6px 12px',
              borderRadius: '4px',
              cursor: 'pointer',
              fontSize: '11px',
              fontWeight: tab === t ? 'bold' : 'normal',
            }}
          >
            {t === 'nl-math' ? 'NL Math' : t.charAt(0).toUpperCase() + t.slice(1)}
          </button>
        ))}
      </div>

      {/* Content */}
      <div style={{ flex: 1, overflowY: 'auto', padding: '12px', display: 'flex', flexDirection: 'column' }}>
        {/* Display */}
        <div
          style={{
            backgroundColor: '#1a1f3a',
            border: '2px solid #00ff88',
            borderRadius: '4px',
            padding: '12px',
            marginBottom: '12px',
            color: '#00ff88',
            fontSize: '24px',
            fontWeight: 'bold',
            textAlign: 'right',
            minHeight: '50px',
            wordWrap: 'break-word',
            wordBreak: 'break-all',
          }}
        >
          {display}
        </div>

        {tab === 'basic' && (
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '6px' }}>
            {/* First Row */}
            <button onClick={clear} style={{ ...btnStyle, gridColumn: '1 / 3' }}>
              CLEAR
            </button>
            <button onClick={backspace} style={btnStyle}>
              ⌫
            </button>
            <button onClick={() => performOperation('/')} style={operatorStyle}>
              ÷
            </button>

            {/* Number Rows */}
            {[7, 8, 9].map((num) => (
              <button key={num} onClick={() => inputDigit(num)} style={btnStyle}>
                {num}
              </button>
            ))}
            <button onClick={() => performOperation('*')} style={operatorStyle}>
              ×
            </button>

            {[4, 5, 6].map((num) => (
              <button key={num} onClick={() => inputDigit(num)} style={btnStyle}>
                {num}
              </button>
            ))}
            <button onClick={() => performOperation('-')} style={operatorStyle}>
              −
            </button>

            {[1, 2, 3].map((num) => (
              <button key={num} onClick={() => inputDigit(num)} style={btnStyle}>
                {num}
              </button>
            ))}
            <button onClick={() => performOperation('+')} style={operatorStyle}>
              +
            </button>

            {/* Last Row */}
            <button onClick={() => inputDigit(0)} style={{ ...btnStyle, gridColumn: '1 / 3' }}>
              0
            </button>
            <button onClick={inputDecimal} style={btnStyle}>
              .
            </button>
            <button onClick={equals} style={equalsStyle}>
              =
            </button>
          </div>
        )}

        {tab === 'scientific' && (
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '6px' }}>
            {/* Angle Mode */}
            <div style={{ gridColumn: '1 / 4', marginBottom: '8px' }}>
              <label style={{ color: '#00ff88', fontSize: '11px', marginRight: '12px' }}>
                <input
                  type="radio"
                  name="angle"
                  value="deg"
                  checked={angleMode === 'deg'}
                  onChange={(e) => setAngleMode(e.target.value)}
                  style={{ marginRight: '4px' }}
                />
                Degrees
              </label>
              <label style={{ color: '#00ff88', fontSize: '11px' }}>
                <input
                  type="radio"
                  name="angle"
                  value="rad"
                  checked={angleMode === 'rad'}
                  onChange={(e) => setAngleMode(e.target.value)}
                  style={{ marginRight: '4px' }}
                />
                Radians
              </label>
            </div>

            {/* Trigonometric */}
            {['sin', 'cos', 'tan'].map((func) => (
              <button
                key={func}
                onClick={() => scientificFunc(func)}
                style={{
                  ...btnStyle,
                  color: '#ffff00',
                  backgroundColor: '#00ff8833',
                }}
              >
                {func.toUpperCase()}
              </button>
            ))}

            {/* Math Functions */}
            {['sqrt', 'log', 'ln'].map((func) => (
              <button
                key={func}
                onClick={() => scientificFunc(func)}
                style={{
                  ...btnStyle,
                  color: '#ffff00',
                  backgroundColor: '#00ff8833',
                }}
              >
                {func.toUpperCase()}
              </button>
            ))}

            {/* Constants & Special */}
            <button
              onClick={() => scientificFunc('pi')}
              style={{
                ...btnStyle,
                color: '#ffff00',
                backgroundColor: '#00ff8833',
              }}
            >
              π
            </button>
            <button
              onClick={() => scientificFunc('e')}
              style={{
                ...btnStyle,
                color: '#ffff00',
                backgroundColor: '#00ff8833',
              }}
            >
              e
            </button>
            <button
              onClick={() => scientificFunc('factorial')}
              style={{
                ...btnStyle,
                color: '#ffff00',
                backgroundColor: '#00ff8833',
              }}
            >
              !
            </button>

            {/* Power */}
            <button
              onClick={() => performOperation('^')}
              style={{
                ...btnStyle,
                color: '#ffff00',
                backgroundColor: '#00ff8833',
                gridColumn: '1 / 4',
              }}
            >
              x ^ y (Power)
            </button>
          </div>
        )}

        {tab === 'nl-math' && (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
            <div style={{ fontSize: '11px', color: '#00aa66', marginBottom: '8px' }}>
              💭 Ask in natural language: "What is 50% of 200?" or "Calculate 5 squared plus 3"
            </div>
            <textarea
              value={nlInput}
              onChange={(e) => setNlInput(e.target.value)}
              onKeyPress={(e) => e.key === 'Enter' && !aiLoading && interpretMathQuery()}
              placeholder="Type your math question..."
              style={{
                padding: '8px',
                backgroundColor: '#1a1f3a',
                border: '1px solid #00ff88',
                color: '#00ff88',
                borderRadius: '4px',
                fontSize: '12px',
                minHeight: '60px',
                resize: 'none',
              }}
            />
            <button
              onClick={interpretMathQuery}
              disabled={!nlInput.trim() || aiLoading}
              style={{
                padding: '10px',
                backgroundColor: aiLoading || !nlInput.trim() ? '#00ff8866' : '#00ff88',
                color: '#0a0e27',
                border: 'none',
                borderRadius: '4px',
                fontWeight: 'bold',
                cursor: aiLoading || !nlInput.trim() ? 'not-allowed' : 'pointer',
              }}
            >
              {aiLoading ? 'Calculating...' : 'Calculate'}
            </button>

            {nlResult && (
              <div
                style={{
                  backgroundColor: '#1a1f3a',
                  border: '1px solid #00ff88',
                  borderRadius: '4px',
                  padding: '10px',
                  color: '#cccccc',
                  fontSize: '11px',
                  whiteSpace: 'pre-wrap',
                  maxHeight: '150px',
                  overflowY: 'auto',
                }}
              >
                <div style={{ color: '#ffff00', fontWeight: 'bold', marginBottom: '6px' }}>
                  Query: {nlResult.query}
                </div>
                <div>{nlResult.result}</div>
                <div style={{ color: '#00aa66', fontSize: '10px', marginTop: '6px' }}>
                  {nlResult.timestamp}
                </div>
              </div>
            )}
          </div>
        )}
      </div>

      {/* Resize Handle */}
      <div
        onMouseDown={resizable.onResizeStart}
        style={{
          width: '20px',
          height: '20px',
          position: 'absolute',
          bottom: '0',
          right: '0',
          cursor: 'nwse-resize',
          background: 'linear-gradient(135deg, transparent 50%, #00ff88 50%)',
          borderRadius: '0 0 8px 0',
        }}
      />
    </div>
  );
};

export default CalculatorWidget;
